import os
import secrets
from datetime import datetime, timedelta, timezone
from functools import wraps
from pathlib import Path

import jwt
from flask import Flask, current_app, g, jsonify, request
from werkzeug.security import check_password_hash, generate_password_hash

from notification_tasks import send_notification_email
from repositories import BaseRepository, TaskRepository, UserRepository, init_storage


_default_jwt_secret = secrets.token_bytes(32)


def _json_body() -> dict | None:
    data = request.get_json(silent=True)
    return data if isinstance(data, dict) else None


def _valid_credentials(data: dict | None) -> tuple[str, str] | None:
    if data is None:
        return None
    username = data.get("username")
    password = data.get("password")
    if not isinstance(username, str) or not username.strip():
        return None
    if not isinstance(password, str) or not password:
        return None
    return username.strip(), password


def _authentication_required(view):
    @wraps(view)
    def wrapped(*args, **kwargs):
        authorization = request.headers.get("Authorization", "")
        scheme, separator, token = authorization.partition(" ")
        if not separator or scheme.lower() != "bearer" or not token:
            return jsonify(error="authentication required"), 401
        try:
            payload = jwt.decode(
                token,
                current_app.config["JWT_SECRET_KEY"],
                algorithms=["HS256"],
            )
            user_id = int(payload["sub"])
        except (jwt.PyJWTError, KeyError, TypeError, ValueError):
            return jsonify(error="invalid token"), 401

        user_repository = current_app.extensions["user_repository"]
        user = user_repository.get_by_id(user_id)
        if user is None:
            return jsonify(error="invalid token"), 401
        g.current_user = user
        return view(*args, **kwargs)

    return wrapped


def create_app(config: dict | None = None) -> Flask:
    app = Flask(__name__)
    app.config.from_mapping(
        TASKS_FILE=os.environ.get(
            "TASKS_FILE", str(Path(app.instance_path) / "tasks.json")
        ),
        JWT_SECRET_KEY=os.environ.get("JWT_SECRET_KEY", _default_jwt_secret),
        JWT_EXPIRATION_SECONDS=3600,
    )
    if config:
        app.config.update(config)
    if not app.config.get("USERS_FILE"):
        app.config["USERS_FILE"] = str(
            Path(app.config["TASKS_FILE"]).with_name("users.json")
        )

    task_repository, user_repository = init_storage(
        app.config["TASKS_FILE"], app.config["USERS_FILE"]
    )
    app.extensions["task_repository"] = task_repository
    app.extensions["user_repository"] = user_repository

    @app.post("/auth/register")
    def register():
        data = _json_body()
        credentials = _valid_credentials(data)
        if credentials is None:
            return jsonify(error="username and password are required"), 400
        username, password = credentials
        email = data.get("email")
        if email is not None and (
            not isinstance(email, str) or not email.strip()
        ):
            return jsonify(error="email must be a non-empty string"), 400

        user = user_repository.create_user(
            username,
            email.strip() if email is not None else username,
            generate_password_hash(password, method="scrypt"),
        )
        if user is None:
            return jsonify(error="username already exists"), 409
        return jsonify(id=user["id"], username=user["username"]), 201

    @app.post("/auth/login")
    def login():
        credentials = _valid_credentials(_json_body())
        if credentials is None:
            return jsonify(error="username and password are required"), 400
        username, password = credentials

        user = user_repository.get_by_username(username)
        if user is None or not check_password_hash(user["password_hash"], password):
            return jsonify(error="invalid username or password"), 401

        now = datetime.now(timezone.utc)
        token = jwt.encode(
            {
                "sub": str(user["id"]),
                "iat": now,
                "exp": now
                + timedelta(seconds=app.config["JWT_EXPIRATION_SECONDS"]),
            },
            app.config["JWT_SECRET_KEY"],
            algorithm="HS256",
        )
        return jsonify(token=token)

    @app.post("/tasks")
    @_authentication_required
    def create_task():
        data = _json_body()
        title = data.get("title") if data is not None else None
        if not isinstance(title, str) or not title.strip():
            return jsonify(error="title is required"), 400

        task = task_repository.create_for_owner(
            title.strip(),
            g.current_user["id"],
            datetime.now(timezone.utc).isoformat(),
        )
        return jsonify(task), 201

    @app.get("/tasks")
    @_authentication_required
    def list_tasks():
        tasks = task_repository.list_for_owner(g.current_user["id"])
        return jsonify(tasks)

    @app.get("/tasks/<int:task_id>")
    @_authentication_required
    def get_task(task_id: int):
        task = task_repository.get_for_owner(task_id, g.current_user["id"])
        if task is None:
            return jsonify(error="task not found"), 404
        return jsonify(task)

    @app.put("/tasks/<int:task_id>")
    @_authentication_required
    def update_task(task_id: int):
        data = _json_body()
        if data is None:
            return jsonify(error="JSON object is required"), 400

        if "title" in data and (
            not isinstance(data["title"], str) or not data["title"].strip()
        ):
            return jsonify(error="title must be a non-empty string"), 400
        if "status" in data and (
            not isinstance(data["status"], str) or not data["status"].strip()
        ):
            return jsonify(error="status must be a non-empty string"), 400
        if not any(field in data for field in ("title", "status")):
            return jsonify(error="title or status is required"), 400

        changes = {
            field: data[field].strip()
            for field in ("title", "status")
            if field in data
        }
        updated = task_repository.update_for_owner(
            task_id, g.current_user["id"], changes
        )
        if updated is None:
            return jsonify(error="task not found"), 404
        task_result, previous_task = updated
        status_changed_to_completed = (
            task_result.get("status") == "completed"
            and previous_task.get("status") != "completed"
        )
        if status_changed_to_completed:
            owner_email = g.current_user.get("email", g.current_user["username"])
            send_notification_email.delay(owner_email, task_result["title"])
        return jsonify(task_result)

    return app


app = create_app()


if __name__ == "__main__":
    app.run()

import json
import os
import tempfile
import threading
from abc import ABC, abstractmethod
from pathlib import Path
from typing import Any


_storage_lock = threading.RLock()


class BaseRepository(ABC):
    """File-backed repository with common CRUD operations."""

    def __init__(self, path: str | os.PathLike[str]) -> None:
        self.path = Path(path)
        self._initialize()

    @property
    @abstractmethod
    def entity_name(self) -> str:
        """Human-readable entity name used in storage errors."""

    def _initialize(self) -> None:
        with _storage_lock:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            if not self.path.exists():
                self.path.write_text("[]\n", encoding="utf-8")

    def _read(self) -> list[dict[str, Any]]:
        self._initialize()
        try:
            data = json.loads(self.path.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError) as exc:
            raise RuntimeError(f"{self.entity_name} storage could not be read") from exc
        if not isinstance(data, list):
            raise RuntimeError(f"{self.entity_name} storage has an invalid format")
        return data

    def _write(self, records: list[dict[str, Any]]) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        fd, temporary_name = tempfile.mkstemp(
            dir=self.path.parent, prefix=f".{self.path.name}.", text=True
        )
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as temporary_file:
                json.dump(records, temporary_file, indent=2)
                temporary_file.write("\n")
                temporary_file.flush()
                os.fsync(temporary_file.fileno())
            os.replace(temporary_name, self.path)
        except BaseException:
            try:
                os.unlink(temporary_name)
            except FileNotFoundError:
                pass
            raise

    def get_all(self) -> list[dict[str, Any]]:
        with _storage_lock:
            return [record.copy() for record in self._read()]

    def get_by_id(self, record_id: int) -> dict[str, Any] | None:
        with _storage_lock:
            record = next(
                (record for record in self._read() if record["id"] == record_id),
                None,
            )
            return record.copy() if record is not None else None

    def create(self, attributes: dict[str, Any]) -> dict[str, Any]:
        with _storage_lock:
            records = self._read()
            record = {
                **attributes,
                "id": max((item["id"] for item in records), default=0) + 1,
            }
            records.append(record)
            self._write(records)
            return record.copy()

    def update(
        self, record_id: int, attributes: dict[str, Any]
    ) -> dict[str, Any] | None:
        with _storage_lock:
            records = self._read()
            record = next(
                (record for record in records if record["id"] == record_id), None
            )
            if record is None:
                return None
            record.update(attributes)
            self._write(records)
            return record.copy()

    def delete(self, record_id: int) -> bool:
        with _storage_lock:
            records = self._read()
            remaining = [record for record in records if record["id"] != record_id]
            if len(remaining) == len(records):
                return False
            self._write(remaining)
            return True


class TaskRepository(BaseRepository):
    @property
    def entity_name(self) -> str:
        return "Task"

    def __init__(self, path: str | os.PathLike[str]) -> None:
        super().__init__(path)
        self._migrate_legacy_tasks()

    def _migrate_legacy_tasks(self) -> None:
        with _storage_lock:
            tasks = self._read()
            migrated = False
            for task in tasks:
                if "owner_id" not in task:
                    task["owner_id"] = None
                    migrated = True
            if migrated:
                self._write(tasks)

    def create_for_owner(
        self, title: str, owner_id: int, created_at: str
    ) -> dict[str, Any]:
        return self.create(
            {
                "title": title,
                "status": "pending",
                "created_at": created_at,
                "owner_id": owner_id,
            }
        )

    def list_for_owner(self, owner_id: int) -> list[dict[str, Any]]:
        tasks = [
            task for task in self.get_all() if task.get("owner_id") == owner_id
        ]
        return sorted(tasks, key=lambda task: task["created_at"], reverse=True)

    def get_for_owner(self, task_id: int, owner_id: int) -> dict[str, Any] | None:
        task = self.get_by_id(task_id)
        if task is None or task.get("owner_id") != owner_id:
            return None
        return task

    def update_for_owner(
        self, task_id: int, owner_id: int, attributes: dict[str, Any]
    ) -> tuple[dict[str, Any], dict[str, Any]] | None:
        with _storage_lock:
            tasks = self._read()
            task = next(
                (
                    task
                    for task in tasks
                    if task["id"] == task_id and task.get("owner_id") == owner_id
                ),
                None,
            )
            if task is None:
                return None
            previous = task.copy()
            task.update(attributes)
            self._write(tasks)
            return task.copy(), previous


class UserRepository(BaseRepository):
    @property
    def entity_name(self) -> str:
        return "User"

    def get_by_username(self, username: str) -> dict[str, Any] | None:
        with _storage_lock:
            user = next(
                (user for user in self._read() if user["username"] == username),
                None,
            )
            return user.copy() if user is not None else None

    def create_user(
        self, username: str, email: str, password_hash: str
    ) -> dict[str, Any] | None:
        with _storage_lock:
            users = self._read()
            if any(user["username"] == username for user in users):
                return None
            user = {
                "id": max((item["id"] for item in users), default=0) + 1,
                "username": username,
                "email": email,
                "password_hash": password_hash,
            }
            users.append(user)
            self._write(users)
            return user.copy()


def init_storage(
    tasks_path: str | os.PathLike[str], users_path: str | os.PathLike[str]
) -> tuple[TaskRepository, UserRepository]:
    """Initialize application storage and return its repositories."""
    return TaskRepository(tasks_path), UserRepository(users_path)

